namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public int? CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string id);
    IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including statistics." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and cultures." },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = "cs",
            InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on programming pedagogy.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS201", Title = "Data Structures & Algorithms",
            Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = "cs",
            InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has industry experience at major tech companies.",
            IsFeatured = true
        },
        new()
        {
            Id = 3, CourseCode = "CS310", Title = "Database Systems",
            Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL systems.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = "cs",
            InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect for 10 years before joining academia."
        },
        new()
        {
            Id = 4, CourseCode = "MATH101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = "math",
            InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has authored two calculus textbooks.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH250", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications in data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = "math",
            InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang researches applied linear algebra with a focus on machine learning applications."
        },
        new()
        {
            Id = 6, CourseCode = "ENG101", Title = "Composition & Rhetoric",
            Description = "Develop effective writing skills through essays, research papers, and rhetorical analysis.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = "eng",
            InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing coach with expertise in academic and creative writing."
        },
        new()
        {
            Id = 7, CourseCode = "ENG220", Title = "American Literature",
            Description = "Survey of American literary works from the colonial period to the present, including novels, poetry, and drama.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = "eng",
            InstructorName = "Dr. Angela Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has published extensively on multicultural literature.",
            IsFeatured = true
        },
        new()
        {
            Id = 8, CourseCode = "PHYS101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = "phys",
            InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster conducts research in experimental physics and emphasizes hands-on learning."
        },
        new()
        {
            Id = 9, CourseCode = "PHYS210", Title = "Electromagnetism",
            Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
            Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = "phys",
            InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma is a theoretical physicist with publications in quantum electrodynamics."
        },
        new()
        {
            Id = 10, CourseCode = "HIST101", Title = "World History to 1500",
            Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the medieval period.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = "hist",
            InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is an archaeologist and historian specializing in ancient Mediterranean civilizations."
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string id) =>
        Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollment(EnrollmentRequest request) => true;
}

